use super::prelude::*;

/// Wish (Ancient-rarity Skill, Cost 0). The player picks one draw-pile
/// card and it goes to hand. `Wish.cs` is identical in v0.107.1 and
/// v0.111.0 (the game prompts for the pick); the pre-0.111 auto-pick
/// below is kept only to preserve the existing v0.107.1 trace baseline
/// and does not match the game, while `>= V0_111_0` follows the game.
///
/// Pre-0.111 auto-pick, port-pin
/// `sts2-rl-agent@01c094d:sts2_env/cards/status.py::wish_effect`:
/// `ordered = sorted(combat.draw_pile, key=lambda c: (c.rarity.value,
/// c.card_id.value))`; the leftmost entry is taken deterministically,
/// the same collapse convention as [`play_dual_wield`], which lands on
/// the lowest-`(rarity, card_id)`
/// draw card (ascending by Python's auto()-assigned rarity values:
/// BASIC < COMMON < UNCOMMON < RARE < ANCIENT < STATUS < CURSE <
/// EVENT < QUEST). Cards whose rarity can't be resolved by
/// [`card_rarity_for_id`] sort last (rarity_key = u8::MAX) so they
/// don't poison the chosen-card calc. No-op when the draw pile is
/// empty. Bead `sts2-rs-d8i4` (6ynt.8-wish).
///
/// Version split. On `>= V0_111_0` the card follows the game's
/// `Wish.cs` `OnPlay` (a `CardSelectCmd.FromCombatPile` over the whole
/// draw pile, `prefs(1)`): the draw pile is offered as a single-pick
/// choice sorted by `(rarity, name)`, via
/// [`move_card_from_draw_to_hand_filtered`] with no type filter (0
/// cards = no-op, exactly 1 = moved with no prompt). On earlier builds
/// the deterministic auto-pick described above is kept unchanged so the
/// v0.107.1 trace regression is unaffected.
pub(crate) fn play_wish(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    if state.game_version >= sts2_core::GameVersion::V0_111_0 {
        move_card_from_draw_to_hand_filtered(state, None);
        return EffectResult::Resolved;
    }
    if state.player.draw.is_empty() {
        return EffectResult::Resolved;
    }
    let pick = state
        .player
        .draw
        .iter()
        .copied()
        .min_by_key(|uid| {
            let idx = uid.0.get() as usize - 1;
            let card_id = state.cards[idx].card_id;
            (
                rarity_sort_key(card_rarity_for_id_in(card_id, state.game_version)),
                card_id,
            )
        })
        .expect("draw non-empty above");
    state.move_card_to_hand(pick);
    EffectResult::Resolved
}
